-- ========================================================


function QuestCore:__init( questID_ )

    -- ----- 源自配表信息: -----
    self.questID = questID_ -- int -- 例: 1001;  需严格对应 配表中数据
    assert( not isNull(self.questID) and (self.questID~="") )
    self.questTitle = nil  --  string 数据源自配表
    self.questDescription = nil -- string 数据源自配表


    self.tasks = {} -- Task[]

    -- 当前所处的 task 的 idx 值:
    self.currentTaskIdx = 0 -- int

    -- id 信息映射表:
    self.taskIDStr2Idx = {} -- Dictionary<string,int> {"T001",0} 开始


    --  机关(gear) 可以注册本事件, 以便在 task切换 时 修改自己的状态; 
    self.BeforeTaskSwitchFuncs = {} -- Action<TaskSwitchData>
    self.AfterTaskSwitchFuncs = {} -- Action<TaskSwitchData>


    -- 当执行完最后一个 task, 且在 quest 进入收尾工作之前, 用户可注册本事件来执行一些收尾工作
    self.BeforeQuestFinishFuncs = {}


    self.OnRunFirstTaskFuncs = {} -- Action
    self.OnSwitchTaskFunc = nil -- Func<TaskSwitchData,IEnumerator>
    self.OnHandleLastTaskFunc = nil -- Func<TaskSwitchData,IEnumerator>


    self.isInit = false -- bool
end


function QuestCore:__delete()
end



-- =========================================== Self ================================================ --



function QuestCore:AddTask(task_)
    self.taskIDStr2Idx[task_.taskID] = table.count( self.taskIDStr2Idx ) -- {"T001", 0} starts

    --tasks[#tasks + 1] = task_
    table.insert( self.tasks, task_ )
end


function QuestCore:GetTaskIdx(taskID_)
    assert( not isNull( self.taskIDStr2Idx[taskID_] ), "taskID_ = " .. tostring(taskID_) )
    return self.taskIDStr2Idx[taskID_]
end


function QuestCore:GetTask(taskIdx_)
    assert( self.tasks[ taskIdx_+1 ] )
    return self.tasks[ taskIdx_+1 ]
end


-- 每个机关 (gear) 自己持有一个 taskRange, 表示自己会在哪段 task区间内 保持激活;
-- 每个机关调用本函数, 来得知自己是否 active; 
function QuestCore:IsGearActive(gearTaskRange_)
    return gearTaskRange_:IsInRange( self.currentTaskIdx )
end


-- 机关调用此函数来运行 quest 中的第一个 task:
-- 运行后 currentTaskIdx 依然指向 0, 此过程内不存在 ToNextTask() 功能;
function QuestCore:RunFirstTask()
    for _, handler in pairs(self.OnRunFirstTaskFuncs) do
        handler()
    end
end



-- task 切换总流程:
-- 需要由机关(gear) 来主动调用本函数, (在机关觉得合适的时机点上)
-- 若执行此 task切换 后, new task 恰好为最后一个 task, 则需要执行额外的收尾工作: HandleLastTask()
-- ---
-- 允许派生类自定义 新的流程;
function QuestCore:ToNextTask(taskRange_)
    assert( self:IsGearActive(taskRange_), "currentTaskIdx: " .. self.currentTaskIdx .. "; range: " .. tostring(taskRange_))
        
    local taskSwitchData = TaskSwitchData.New( self.currentTaskIdx, self.currentTaskIdx + 1 ) 

    if taskSwitchData.newTaskIdx > #self.tasks - 1 then
        printError( "currentTaskIdx 异常: " .. tostring(taskSwitchData) .. "; tasks.Count = " .. #self.tasks )
        return
    end
    
    -- 执行 task 切换：
    self:CallBeforeTaskSwitch(taskSwitchData)
    cs_coroutine.yield_return( self:SwitchTask(taskSwitchData) )

    self:CallAfterTaskSwitch(taskSwitchData)

    self.currentTaskIdx = self.currentTaskIdx + 1

    -- task0 是起始状态, 本质上它不算一个 task, 所以这个 0-based idx 恰好等于 taskNum: 
    DreamSpaceStates.FinshedTaskNum = self.currentTaskIdx

    
    -- 当切换进最后一个 task 时，需要执行额外的收尾工作：
    if taskSwitchData.newTaskIdx == #self.tasks - 1 then
        cs_coroutine.yield_return( self:HandleLastTask(taskSwitchData) )
    end
end




function QuestCore:SwitchTask(taskSwitchData_)
    if self.OnSwitchTaskFunc ~= nil then 
        self.OnSwitchTaskFunc(taskSwitchData_)
    end
end



function QuestCore:HandleLastTask(taskSwitchData_)
    if self.OnHandleLastTaskFunc ~= nil then 
        self.OnHandleLastTaskFunc(taskSwitchData_)
    end
end


-- 注意, CallBeforeTaskSwitch() 和 CallAfterTaskSwitch() 的参数最好保持相同;
function QuestCore:CallBeforeTaskSwitch(taskSwitchData_)
    for _, handler in pairs(self.BeforeTaskSwitchFuncs) do
        cs_coroutine.yield_return( handler(taskSwitchData_) )
    end
end


function QuestCore:CallAfterTaskSwitch(taskSwitchData_)
    for _, handler in pairs(self.AfterTaskSwitchFuncs) do
        cs_coroutine.yield_return( handler(taskSwitchData_) )
    end
end


function QuestCore:CallBeforeQuestFinish()
    for _, handler in pairs(self.BeforeQuestFinishFuncs) do
        cs_coroutine.yield_return( handler() )
    end
end


function QuestCore:DebugPrint()
    local s = " questID: " .. self.questID
    s = s .. "\n questTitle: " .. self.questTitle
    s = s .. "\n questDescription: " .. self.questDescription
    s = s .. "\n tasks:"

    for i, t in ipairs(self.tasks) do
        s = s .. "\n     taskID: " .. t.taskID
        s = s .. "\n     taskDescription: " .. t.taskDescription
    end
    print(s)
end






return QuestCore

